{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "རིམ་ལྔ་ལས།",
      "head": "གཟུགས་བཅས་འོད་ཟེར་དེ་",
      "tail": "སྒྱུ་འཕྲུལ་དྲྭ་བ་འབྱུང་བར་འགྱུར། །"
    },
    {
      "label": "QUOTE",
      "head": "ཀུན་རྫོབ་དང་ནི་དོན་དམ་གཉིས། ། སོ་སོའི་ཆ་ནི་ཤེས་གྱུར་ནས། ། གང་དུ་ཡང་དག་འདྲེས་གྱུར་པ། ། ཟུང་དུ་འཇུག་པར་དེ་བཤད་དོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ཉིད་ཤེས་པས་རིམ་པ་བཞིན། ། རང་བྱིན་བརླབ་དང་འོད་གསལ་ཤེས། ། དེ་དག་ཁོ་ན་བསྡུས་པ་གང༌། ། འདི་ནི་ཟུང་འཇུག་རིམ་པའོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རིམ་ལྔ་ལས།",
      "head": "གང་དུ་གང་ཟག་བདག་མེད་",
      "tail": "ཟུང་དུ་འཇུག་པའི་མཚན་ཉིད་དོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "སྤྱོད་བསྡུས་ལས།",
      "head": "ཇི་ལྟར་རྒྱལ་པོ་ཨིནྡྲ་བྷུ",
      "tail": "སངས་རྒྱས་ཀྱི་ཞིང་དུ་འགྲོ་སྟེ། །"
    },
    {
      "label": "QUOTE",
      "frame": "རིམ་ལྔ་ལས།",
      "head": "ཟུང་འཇུག་རིག་པ་ལ་གནས་",
      "tail": "སླར་ཞིང་གང་ལའང་མི་སློབ་བོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "དེ་ཉིད་ལས།",
      "head": "ཟུང་འཇུག་རིམ་པ་ལ་གནས་",
      "tail": "སྤྱོད་པའང་དེ་དང་གཉིས་སུ་མེད། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཀརྨ་ཆགས་མེད་ཀྱིས།",
      "head": "ལྷ་ལྔའི་བདག་བསྐྱེད་ཚང་",
      "tail": "བརྒྱ་ལས་རྩ་བརྒྱད་ལྷག་པ་པོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "བདེ་མཆོག་སྡོམ་པ་འབྱུང་བའི་རྒྱུད་ཉིད་ནས།",
      "head": "བུམ་པ་ཅན་སྔར་ཤེས་བྱས་",
      "tail": "བརྒྱ་ལས་རྩ་བརྒྱད་ལྷག་པ་པོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཀལྤ་ལའི་ལུང་དྲངས་དང༌།",
      "head": "སྒྲའི་རང་བཞིན་སྦོམ་པོར་",
      "tail": "རྣལ་འབྱོར་པའི་མཆོག་གི་གནས། །"
    }
  ]
}
